/* Марки та власні назви не перекладаються — просто виводяться як є. */
function ingName(key, lang) {
  if (key.startsWith('~')) return key.slice(1);   // «~Absolut Citron» → як є
  const e = ING[key];
  if (!e) return key;
  return e[lang] || e.en || key;
}
